import * as React from "react"

function MinimalProfileCard({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="minimal-profile-card"
      className={className}
      {...props}
    >
      <div
          className="py-8 px-8 max-w-sm mx-auto bg-white rounded-xl shadow-lg space-y-2 sm4 sm sm sm0 sm6">
          <img className="block mx-auto h-24 rounded-full sm0 sm0" src="https://tailwindcss.com/img/erin-lindford.jpg" alt="Woman's Face" />
          <div className="text-center space-y-2 sm">
              <div className="space-y-0.5">
                  <p className="text-lg text-black font-semibold">
                      Erin Lindford
                  </p>
                  <p className="text-slate-500 font-medium">
                      Product Engineer
                  </p>
              </div>
              <button className="px-4 py-1 text-sm text-purple-600 font-semibold rounded-full border border-purple-200 hover hover600 hover focus focus2 focus600 focus2">Message</button>
          </div>
      </div>
    </div>
  )
}

export { MinimalProfileCard }
